def chunk_words(text, size, overlap):
    if overlap >= size:
        raise ValueError('overlap must be smaller than size')
    words = text.split()
    step = size - overlap
    chunks = []
    start = 0
    while start < len(words):
        chunks.append(' '.join(words[start:start + size]))
        if start + size >= len(words):
            break
        start += step
    return chunks

