ABSTAIN = 'I could not find this in the documentation.'

def grounded_prompt(question, chunks):
    if not chunks:
        return ABSTAIN
    lines = ['<chunk id="%s">%s</chunk>' % (cid, text) for cid, text in chunks]
    lines.append('Answer only from the chunks above and cite chunk ids like [ID]. If they do not contain the answer, say "' + ABSTAIN + '"')
    lines.append('Question: ' + question)
    return '\n'.join(lines)

import re

ABSTAIN = 'I could not find this in the documentation.'

def check_citations(answer, retrieved_ids):
    cited = []
    for cid in re.findall(r'\[([A-Za-z0-9_-]+)\]', answer):
        if cid not in cited:
            cited.append(cid)
    unknown = [c for c in cited if c not in set(retrieved_ids)]
    if answer.strip() == ABSTAIN:
        return {'cited': [], 'unknown': [], 'ok': True}
    return {'cited': cited, 'unknown': unknown, 'ok': bool(cited) and not unknown}
